def even_odd_count(num):
    # Convert negative number to positive
    num = abs(num)

    # Convert number to string
    num_str = str(num)

    even_count = 0
    odd_count = 0

    for digit in num_str:
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

